import{c as l,$ as i,Q as e,j as o,g as s,o as r,n,m as d}from"./chunks/framework.Ce_49mA8.js";const y=JSON.parse('{"title":"О философии проекта","description":"Фундаментальные ценности и инженерные принципы ОмниКрафт ЕРП: событийный учёт без бюрократии, три отчёта, автономность на своём компьютере и ответы на частые вопросы.","frontmatter":{"title":"О философии проекта","description":"Фундаментальные ценности и инженерные принципы ОмниКрафт ЕРП: событийный учёт без бюрократии, три отчёта, автономность на своём компьютере и ответы на частые вопросы.","order":1,"datePublished":"2026-08-20","dateModified":"2026-11-22"},"headers":[],"relativePath":"ru/docs/introduction.md","filePath":"ru/docs/introduction.md","lastUpdated":1795305600000}'),c={name:"ru/docs/introduction.md"},p={id:"о-философии-проекта",tabindex:"-1"};function h(v,t,u,m,g,f){const a=i("DocIcon");return e(),o("div",null,[s("h1",p,[r(a,{name:"philosophy"}),t[0]||(t[0]=n(" О философии проекта ",-1)),t[1]||(t[1]=s("a",{class:"header-anchor",href:"#о-философии-проекта","aria-label":'Permalink to "О философии проекта"'},"​",-1))]),t[2]||(t[2]=d('<p><strong>ОмниКрафт ЕРП</strong> создана для тех, кто создаёт осязаемую ценность своими руками и головой: для мастеров штучного и серийного производства, специалистов сферы услуг и независимых предпринимателей с практическим бизнес-мышлением.</p><p>Классический бухгалтерский учёт создавался под требования контролирующих органов: он перегружен бесконечными накладными, заумными планами счетов и формальными проводками. Типовые мобильные приложения для личных трат требуют нудного сканирования чеков из супермаркетов, но совершенно не понимают себестоимости изделий, заказ-нарядов и амортизации оборудования.</p><p>В основу ОмниКрафт ЕРП заложен <strong>инженерный прагматизм</strong>: учёт обязан служить делу, требовать минимум времени и честно показывать реальную отдачу от каждого вложенного часа и рубля.</p><hr><h2 id="четыре-фундаментальных-принципа-омникрафт-ерп" tabindex="-1">Четыре фундаментальных принципа ОмниКрафт ЕРП <a class="header-anchor" href="#четыре-фундаментальных-принципа-омникрафт-ерп" aria-label="Permalink to &quot;Четыре фундаментальных принципа ОмниКрафт ЕРП&quot;">​</a></h2><h3 id="_1-событииныи-учет-вместо-бухгалтерскои-бюрократии" tabindex="-1">1. Событийный учёт вместо бухгалтерской бюрократии <a class="header-anchor" href="#_1-событииныи-учет-вместо-бухгалтерскои-бюрократии" aria-label="Permalink to &quot;1. Событийный учёт вместо бухгалтерской бюрократии&quot;">​</a></h3><p>Система исключает двойную работу и ведение виртуальных проводок. Управленческая аналитика рождается непосредственно из естественных физических событий вашей мастерской или сервиса:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>В ремесле и производстве:</strong> при закупке партии сырья расходы на доставку автоматически распределяются в себестоимость каждого дециметра, килограмма или погонного метра. При сборке изделия материалы списываются по скользящей средней стоимости (МАК), а готовая продукция отгружается по методу первых партий (ФИФО), моментально фиксируя чистую маржу.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>В сфере услуг и сервиса:</strong> работа строится через наглядные заказ-наряды. Программа учитывает ставку вашего нормо-часа, автоматически списывает сопутствующие расходники со склада прямо внутри карточки заказа и принимает оплату в кассу без оформления накладных.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Непрерывный синхронный пересчёт:</strong> любое завершённое действие — приёмка материалов, закрытие заказ-наряда, выпуск партии или продажа с витрины — в ту же секунду обновляет складские остатки, кассовый баланс и финансовый результат.</div></li></ul><div class="info custom-block"><p class="custom-block-title">Принцип первичности реального действия</p><p>Вы фиксируете только настоящее рабочее действие мастера — касса, остатки сырья, себестоимость изделий и итоговая операционная прибыль пересчитываются моментально и согласованно.</p></div><h3 id="_2-финансовая-эволюция-от-первых-заказов-до-управления-капиталом" tabindex="-1">2. Финансовая эволюция: от первых заказов до управления капиталом <a class="header-anchor" href="#_2-финансовая-эволюция-от-первых-заказов-до-управления-капиталом" aria-label="Permalink to &quot;2. Финансовая эволюция: от первых заказов до управления капиталом&quot;">​</a></h3><p>Большинство учётных программ либо навязывают новичку громоздкую отчётность крупного завода, либо бросают предпринимателя, когда его деятельность перерастает одну простую таблицу. В ОмниКрафт ЕРП заложено плавное масштабирование по мере роста дела:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Прагматичный старт без лишних формальностей:</strong> на начальном этапе мастера часто оплачивают сырьё личной банковской картой, а выручку направляют на текущие бытовые расходы. Для программы это норма: учитываются только производственные и сервисные операции, а отрицательный баланс в отчёте ДДС честно показывает сумму ваших стартовых вложений в проект, пока он не выйдет на самоокупаемость.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Изолированные рабочие пространства:</strong> когда у вас появляется несколько направлений (например, ремесленная мастерская, сервисный кабинет и розничная витрина), каждое из них ведётся в независимом пространстве со своей кассой, складом и клиентской базой.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Личные финансы без рутины чеков (пространство «Мой капитал»):</strong> для учёта семейного бюджета, накоплений, инвестиций и недвижимости вам не придётся ежедневно записывать мелкие бытовые чеки. В ПРО-режиме личные расходы рассчитываются автоматически по балансовой дельте капитала: достаточно раз в месяц сверить остатки на счетах, и система сама вычислит реальные траты семьи.</div></li></ul><div class="tip custom-block"><p class="custom-block-title">Плавное масштабирование</p><p>Вы начинаете с одного экрана и привычных повседневных операций — за рабочим столом, станком или приёмом заказов. По мере роста дела система открывает возможности раздельного учёта нескольких проектов и консолидации всего личного капитала владельца без переучивания и потери накопленной истории.</p></div><h3 id="_3-баланс-активов-и-реальныи-финансовыи-результат" tabindex="-1">3. Баланс активов и реальный финансовый результат <a class="header-anchor" href="#_3-баланс-активов-и-реальныи-финансовыи-результат" aria-label="Permalink to &quot;3. Баланс активов и реальный финансовый результат&quot;">​</a></h3><p>Покупка лазерного станка, паяльной станции, профессионального аппарата мастера или ручного инструмента уменьшает остаток денег на счёте. Однако ваши средства не исчезли — свободные деньги просто перешли в форму надёжного производственного оборудования, которое продолжает приносить доход.</p><p>Баланс активов и чистая стоимость всего вашего дела рассчитываются непрерывно:</p><div class="craft-callout craft-callout-info"><div class="callout-header">Формула чистых активов (Собственный капитал)</div><p><strong>Капитал бизнеса</strong> = Оборудование и станки (по остаточной стоимости) + Сырьё и расходники на складе (по МАК) + Готовая продукция (по себестоимости) + Свободные деньги в кассах и на счетах − Обязательства и долги бизнеса.</p><p style="margin-top:0.65rem;font-size:0.9em;opacity:0.9;"><strong>Совокупный капитал владельца</strong> (в пространстве «Мой капитал») объединяет чистый капитал производственных направлений с личными инвестициями, недвижимостью и семейными накоплениями за вычетом частных обязательств.</p></div><h4 id="триединство-финансовых-отчетов" tabindex="-1">Триединство финансовых отчётов <a class="header-anchor" href="#триединство-финансовых-отчетов" aria-label="Permalink to &quot;Триединство финансовых отчётов&quot;">​</a></h4><p>Три классических отчёта дополняют друг друга и защищают предпринимателя от опасных иллюзий и кассовых разрывов:</p><div class="comparison-matrix-wrapper"><table class="craft-comparison-table"><thead><tr><th style="width:24%;">Отчёт</th><th style="width:28%;">Главный вопрос</th><th style="width:48%;">Практический смысл для мастера и дела</th></tr></thead><tbody><tr><td><strong>ДДС</strong><br><small style="color:var(--vp-c-text-3);">Движение денег</small></td><td><em>Есть ли средства прямо сейчас?</em></td><td>Отражает физический поток наличных и безналичных оплат. Защищает от кассового разрыва: помогает вовремя оплатить аренду помещения, расходники или счета поставщиков.</td></tr><tr><td><strong>Прибыль (ОПиУ)</strong><br><small style="color:var(--vp-c-text-3);">Финансовый результат</small></td><td><em>Выгодно ли то, что вы делаете?</em></td><td>Сопоставляет реальные доходы с полными расходами (с учётом износа оборудования, списанных материалов и накладных затрат). Показывает истинную прибыльность изделий, заказ-нарядов и услуг.</td></tr><tr><td><strong>Баланс</strong><br><small style="color:var(--vp-c-text-3);">Чистые активы</small></td><td><em>Сколько стоит всё ваше дело?</em></td><td>Объединяет всё имущество (оборудование, инструмент, сырьё, готовые товары, кассу и инвестиции) за вычетом долгов. Показывает, растёт ли ценность вашего дела и личного капитала из года в год.</td></tr></tbody></table></div><div class="tip custom-block"><p class="custom-block-title">Непрерывная финансовая память</p><p>Система непрерывно сохраняет историческую ретроспективу ключевых показателей. Это позволяет наглядно видеть честную динамику развития без риска потери накопленных данных: от сезонных колебаний выручки внутри месяцев до многолетнего роста совокупного капитала дела.</p></div><h3 id="_4-безусловныи-суверенитет-данных-и-локальныи-ии-омни" tabindex="-1">4. Безусловный суверенитет данных и локальный ИИ Омни <a class="header-anchor" href="#_4-безусловныи-суверенитет-данных-и-локальныи-ии-омни" aria-label="Permalink to &quot;4. Безусловный суверенитет данных и локальный ИИ Омни&quot;">​</a></h3><p>ОмниКрафт ЕРП построена на принципах уважения к суверенитету ваших данных. Программа работает автономно на вашем компьютере и не зависит от доступности облачных серверов или риска внезапных блокировок.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Полная локальная автономность:</strong> база данных хранится локально на вашем накопителе. Технологические карты, рецепты изделий, списки клиентов и балансы счетов никогда не передаются на сторонние серверы разработчиков.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Внутренний ИИ-ассистент Омни:</strong> встроенный интеллектуальный напарник выступает в роли опытного цехового наставника и автономного агента. Он помогает в расчётах себестоимости, анализе остатков, ведении заказов и решении прикладных задач мастера через единый реестр инструментов программы и открытый протокол контекста моделей.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Прямой личный ключ доступа к нейросетям без посредников:</strong> запросы к ИИ отправляются с вашего устройства напрямую к выбранному сервису (`OpenAI`, `Google Gemini`, `DeepSeek`, `OpenRouter`) по вашему личному ключу доступа к сервису без промежуточных серверов разработчиков программы. Для тех, кому необходима автономная работа без подключения к сети, поддерживается запуск локальных моделей непосредственно на вашем компьютере через сервис `Ollama`.</div></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><polyline points="20 6 9 17 4 12"></polyline></svg></span><div><strong>Связь с внешними интеллектуальными помощниками (протокол MCP):</strong> позволяет безопасно подключать внешние программы и среды разработки (`Cursor`, `Claude Desktop`, `Antigravity`) для работы с данными вашей мастерской под вашим полным контролем.</div></li></ul><div class="tip custom-block"><p class="custom-block-title">Свобода выбора между облачным и локальным ИИ</p><p>Вы сами определяете контур работы нейросетей. Можно подключить передовые облачные модели по собственному ключу доступа к сервису либо запустить модель на своём компьютере через сервис <code>Ollama</code> — в этом режиме вычисления и решение задач происходят непосредственно на вашем устройстве без доступа к интернету.</p></div><hr><h2 id="частые-вопросы-о-принципах-учета" tabindex="-1">Частые вопросы о принципах учёта <a class="header-anchor" href="#частые-вопросы-о-принципах-учета" aria-label="Permalink to &quot;Частые вопросы о принципах учёта&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Почему программа работает локально на компьютере, а не как облачный сервис?</summary><div class="faq-content"><p>Работа на собственном компьютере гарантирует полную независимость и безопасность ваших коммерческих данных. База хранится исключительно на вашем диске: вся история мастерской упакована в единый компактный файл, который легко скопировать на флешку или перенести на новый рабочий компьютер без сложных настроек и выгрузок. Программа не перестанет открываться из-за сетевых сбоев, блокировок сторонних сервисов или отсутствия интернета на рабочем месте. Вы полноправно владеете своими данными навсегда.</p></div></details><details class="faq-item"><summary class="faq-summary">Можно ли использовать ИИ-ассистента Омни полностью без интернета?</summary><div class="faq-content"><p>Да. Для работы без подключения к сети достаточно подключить бесплатный локальный сервис <code>Ollama</code>. В этом режиме ассистент Омни и инструменты учёта работают напрямую на ресурсах вашего компьютера.</p></div></details><details class="faq-item"><summary class="faq-summary">Заменяет ли ОмниКрафт ЕРП бухгалтерскую и налоговую отчётность (1С, ФНС)?</summary><div class="faq-content"><p>ОмниКрафт ЕРП создана для <strong>управленческого учёта</strong> — чтобы вы в любой момент знали истинную себестоимость изделий, чистую маржу, остатки сырья и объём собственного капитала для принятия верных бизнес-решений. Бухгалтерский учёт для налоговой инспекции ведётся отдельно в личном кабинете налогоплательщика или через приходящего бухгалтера.</p></div></details><details class="faq-item"><summary class="faq-summary">Почему отрицательный остаток в отчёте ДДС на старте считается нормальным?</summary><div class="faq-content"><p>В реальной жизни мастера часто закупают оборудование или первую партию материалов с личной банковской карты без предварительного оформления фиктивного взноса уставного капитала. Программа не блокирует работу: отрицательное сальдо ДДС честно показывает точный объём ваших личных инвестиций в проект, которые бизнес вернёт по мере роста продаж.</p></div></details><details class="faq-item"><summary class="faq-summary">Как программа разделяет личные деньги и бизнес без ежедневного сбора чеков?</summary><div class="faq-content"><p>В пространстве «Мой капитал» действует расчёт по балансовой дельте капитала. Вместо сканирования каждого продуктового чека достаточно раз в месяц зафиксировать остатки на основных банковских счетах и вкладах. Система сопоставит изменение чистых активов с доходами бизнеса и точно определит, сколько средств ушло на жизнь семьи.</p></div></details></div><hr><h2 id="с-чего-начать-изучение" tabindex="-1">С чего начать изучение? <a class="header-anchor" href="#с-чего-начать-изучение" aria-label="Permalink to &quot;С чего начать изучение?&quot;">​</a></h2><div class="cta-grid"><div class="cta-card featured-cta"><div><div class="cta-card-badge brand-badge">Практический старт</div><h3>Быстрый старт и установка</h3><p> Пошаговое руководство от скачивания приложения до выпуска первой партии и расчёта себестоимости за 15 минут. </p></div><a href="/ru/docs/getting-started" class="vp-button brand cta-icon-btn"><span>Перейти к установке</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div><div class="cta-card"><div><div class="cta-card-badge">Архитектура учёта</div><h3>Рабочие пространства</h3><p> Организация независимых направлений: ремесленная мастерская, сервисные заказ-наряды и управление личным капиталом. </p></div><a href="/ru/docs/spaces/general" class="vp-button alt cta-icon-btn"><span>Обзор пространств</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="cta-btn-icon"><line x1="5" y1="12" x2="19" y2="12"></line><polyline points="12 5 19 12 12 19"></polyline></svg></a></div></div>',31))])}const k=l(c,[["render",h]]);export{y as __pageData,k as default};
